	public static function getBasicBodyMessage($compose_message, $pkObject,$modulo_id)
	{
		$body_message = "";
		if(ModuleEnableNotify::ComEnviada == $modulo_id){
			$com_enviada = ComEnviadaPeer::retrieveByPK($pkObject);
			$partial_message = '<b>Numero Radicado:</b> '.$com_enviada->getRadicado().'<br>
			<b>Asunto:</b> '.mb_convert_encoding($com_enviada->getAsunto(), 'UTF-8').'<br>
			<b>Fecha Radicaci&oacute;n:</b> '.$com_enviada->getFechaCreacion().' <br>';
		}
		//*************************************************************************************************
		$body_message = str_replace('{{$PARTIAL_MESSAGE_COMPOSE}}',$partial_message,$compose_message);
		return $body_message;
	}
